SELECT s.student_id,s.student_name,b.subject_name,COUNT(e.student_id) AS attended_exams FROM Students s JOIN Subjects b ON 1 = 1 LEFT JOIN Examinations e ON e.student_id=s.student_id AND e.subject_name=b.subject_name GROUP BY s.student_id,s.student_name,b.subject_name ORDER BY s.student_id ASC,b.subject_name ASC;
